// Impulse Bindings 
//
// Default input bindings for game actions, following the Ada Impulse generic pattern.
// Each impulse maps a named action to a primary key, alternate key, and mouse button.
// The Input_Field offset allows the polling loop to write into the Input struct by index.
//
#define MAX_IMPULSES 32
typedef struct {
  const char  *Name;         // Action name ("forward", "jump", etc.)
  int          Primary;      // SDL_SCANCODE_* for primary key
  int          Alternate;    // SDL_SCANCODE_* for alternate key (0 = none)
  int          Mouse_Button; // SDL_BUTTON_* for mouse (0 = none)
  int          Field_Offset; // offsetof(Input, Field) for direct write
} Impulse_Binding;
#define IMPULSE_BINDINGS_LIST /* Name     Primary Key         Alternate Key       Mouse Button     Input_Field offset      */ \
                              {"forward", SDL_SCANCODE_W,     SDL_SCANCODE_UP,    0,               offsetof(Input, Forward)}, \
                              {"back",    SDL_SCANCODE_S,     SDL_SCANCODE_DOWN,  0,               offsetof(Input, Back)},    \
                              {"left",    SDL_SCANCODE_A,     SDL_SCANCODE_LEFT,  0,               offsetof(Input, Left)},    \
                              {"right",   SDL_SCANCODE_D,     SDL_SCANCODE_RIGHT, 0,               offsetof(Input, Right)},   \
                              {"jump",    SDL_SCANCODE_SPACE, 0,                  0,               offsetof(Input, Jump)},    \
                              {"crouch",  SDL_SCANCODE_LCTRL, SDL_SCANCODE_C,     0,               offsetof(Input, Crouch)},  \
                              {"fire",    0,                  0,                  SDL_BUTTON_LEFT, offsetof(Input, Fire)},

// Console commands
//
// Registered commands are dispatched by the console Submit function. Each command has a name, help text,
// usage string, argument bounds, callback, and an optional Save function for config serialization.
//
// All commands and CVars are accessible from any thread via Submit - the console maintains an
// internal mutex for its log buffer and input history, but command dispatch itself is lock-free.
//
typedef void (*Command_Callback) (int Argc, const char *Argv[]);
typedef const char *(*Command_Save_Fn) (); // Returns a string to write to config, or NULL
typedef struct {
  const char      *Name;             // For example: "bind", "map", "quit", etc.
  const char      *Info;             // One-line description
  const char      *Usage;            // Usage syntax string
  int              Arg_Min, Arg_Max; // Argument count bounds (excluding the command name itself)
  Command_Callback Callback;         // Function called when command is submitted
  Command_Save_Fn  Save;             // Optional: returns config line for saving (NULL = no save)
} Command;

// Forward declarations for the commands
void Cmd_Echo        (int Argc, const char *Argv[]);
void Cmd_Quit        (int Argc, const char *Argv[]);
void Cmd_Help        (int Argc, const char *Argv[]);
void Cmd_Reset       (int Argc, const char *Argv[]);
void Cmd_Reset_All   (int Argc, const char *Argv[]);
void Cmd_Save_Config (int Argc, const char *Argv[]);
void Cmd_Load_Config (int Argc, const char *Argv[]);

// Command registration
#define COMMANDS(_) /* Name         Info                             Usage        Arg Min Arg Max               Callback      */ \
                    _("quit",       "Exit the application",          "",          0,      0,                    Cmd_Quit)        \
                    _("help",       "List all commands and cvars",   "",          0,      0,                    Cmd_Help)        \
                    _("reset",      "Reset a cvar to its default",   "<cvar>",    1,      1,                    Cmd_Reset)       \
                    _("resetall",   "Reset all cvars to defaults",   "",          0,      0,                    Cmd_Reset_All)   \
                    _("saveconfig", "Write archive cvars to q3.cfg", "",          0,      0,                    Cmd_Save_Config) \
                    _("loadconfig", "Load cvars from q3.cfg",        "",          0,      0,                    Cmd_Load_Config) \
                    _("echo",       "Print text to console",         "<text...>", 1,      MAX_COMMAND_ARGS - 1, Cmd_Echo)

// World settings
//
// Each asset group has a dominant coordinate convention, player scale, and camera model. The active world determines physics extents,
// eye height, FOV, and the swizzle applied during asset load. Assets from a non-dominant world get rescaled on load.
//
typedef enum {WORLD_QUAKE3, WORLD_SOURCE, WORLD_UNREAL, WORLD_COUNT} World_Type;
typedef struct {
  const char *Name;
  int   Up_Axis;    // Native up axis before swizzle
  float Unit_Scale; // World units per real-world inch

  // Player bounding volume
  float Player_Height;   // Standing bounding box height
  float Player_Width;    // Bounding box half-width
  vec3  Half_Extents;    // Standing AABB half-extents (x, y, z)
  float Capsule_Spine;   // Half-length of capsule cylindrical midsection

  // Camera
  float Eye_Height;        // Camera height above feet
  float Crouch_Eye_Height; // Camera height crouched
  float Crouch_Height;     // Crouched bounding box height
  float FOV;               // Horizontal field of view

  // Movement physics 
  float Max_Speed;     // Maximum wish speed
  float Gravity;       // Downward acceleration
  float Jump_Velocity; // Instantaneous upward velocity on jump
  float Friction;      // Ground friction coefficient
  float Stop_Speed;    // Speed below which friction uses this as control speed
  float Ground_Accel;  // Acceleration while grounded
  float Air_Accel;     // Acceleration while airborne (strafe-jumping)
  float Step_Size;     // Max stair step height
  float Overbounce;    // Surface clip overshoot factor
  float Walk_Normal;   // Min surface normal Y for walkable floor
  float Ground_Dist;   // Ground trace probe window (units above + below feet)
  float Snap_Down;     // Max distance to snap player down to ground
  float Push_Up;       // Max distance to push player up onto ground
  float Vel_Clamp;     // Maximum velocity magnitude (hard clamp)
  float Step_Decay;    // Stair step camera smoothing decay rate (units/sec)
  float View_Lerp;     // View height interpolation speed (crouch transition)
  float Pitch_Limit;   // Maximum look pitch in radians (~86° at 1.5)

  // Assets
  const char *Default_Pack; // Default base asset archive (e.g. "assets/pak0.pk3")
  const char *Default_Map;  // Default map name (e.g. "oa_dm1.bsp")

  // Presentation and content defaults
  const char *Default_VM_Profile;    // Viewmodel profile name (looked up from VM_PROFILES)
  int         Default_Weapon;        // Weapon_Kind enum value
  const char *Default_Player_Model;  // Default enemy/player model path (NULL = no default)
  const char *Default_Weapon_Model;  // Default held weapon model path  (NULL = no default)
  const char *Default_Enemy_Weapon;  // Default enemy world-model weapon path (NULL = none)
} World_Settings;

