// Assemble a composite Q3 player model (lower + upper + head + weapon) at a given animation frame into merged geometry arrays.
void Entity_Assemble_Frame (const char *Player_Model_Dir,
                            int Legs_Frame, int Torso_Frame,
                            uint Body_Mat, uint Gun_Mat, const float World[12],
                            Vertex **Out_Verts,   uint *Out_Vert_Count,
                            uint   **Out_Indices, uint *Out_Index_Count,
                            uint   **Out_Tex_Ids, uint *Out_Tri_Count);

// Figure_Instance: the runtime representation of any loaded model — weapon viewmodel, player body, NPC, prop
typedef struct {
  Articulated_Figure     Figure;
  GPU_Buffer             Vertex_Buffer, Index_Buffer, Texture_Id_Buffer, Bottom_Level_Scratch;
  Acceleration_Structure Bottom_Level;
  Vertex                *Transformed_Vertices, *Current_Vertices;
  float                  Animation_Time;
  int                    Active_Animation;
  Animation_Blend_State  Blend;
  IK_State               IK;
  GPU_Buffer             IK_Buffer;
  int                    Is_Firing;
  float                  Fire_Time, Bob_Time;
  uint                   Texture_Base_Index;
  vec3                   GL_Origin;
  float                  GL_Yaw;
  GPU_Buffer             Bone_Buffer, Inv_Bind_Buffer, Bone_Parent_Buffer;
  GPU_Buffer             Bone_Weight_Buffer, Bone_Id_Buffer, Pose_Buffer;
  GPU_Buffer             Anim_Buffer;         // Animation bone-local library (all keyframes, uploaded once)
  GPU_Buffer             Bind_Vertex_Buffer;  // Read-only bind-pose vertices for GPU skinning input
  GPU_Buffer             Bone_World_Readback; // Host-visible: pre-InvBind bone world transforms (GPU writes, CPU reads)
  float                 *Bone_World_Mapped;   // Persistently mapped pointer into Bone_World_Readback
  uint8_t                Ray_Mask;
  float                  TLAS_Transform[3][4];
  int                    BLAS_Dirty;
  int                    Skinning_Pending;    // 1 = needs GPU skinning dispatch before BLAS rebuild
  uint                   Skinning_Frame_A, Skinning_Frame_B;
  float                  Skinning_Lerp;
} Figure_Instance;

#define FIGURE_POOL_MAX 64
typedef struct { uint Index; uint Generation; } Figure_Handle;
#define FIGURE_HANDLE_NULL ((Figure_Handle){.Index = UINT32_MAX, .Generation = 0})

typedef struct {
  Figure_Instance Slots[FIGURE_POOL_MAX];
  uint            Generations[FIGURE_POOL_MAX];
  uint            Free_Stack[FIGURE_POOL_MAX];
  uint            Free_Count;
  uint            Active_Count;
  int             Active[FIGURE_POOL_MAX];
} Figure_Pool;

Figure_Handle Figure_Pool_Alloc (Figure_Pool *Pool, Figure_Instance **Out);
void          Figure_Pool_Free  (Figure_Pool *Pool, Figure_Handle Handle);

// Serialises all IK chain data into a GPU storage buffer for consumption by
// the skinning compute shader. The buffer layout is:
//
//   Floats  0– 3: [chain_count, enabled, padding, padding]   (header)
//   Floats  4–15: chain 0 data   (type, bone_root, bone_mid, bone_end,
//                                  target_xyz, weight, angle_limit, enabled, pad, pad)
//   Floats 16–27: chain 1 data   ... and so on
//
// The buffer is reallocated if its current capacity is insufficient.
void IK_Upload (IK_State *IK, GPU_Buffer *IK_Buffer_Out);

// Updates the world-space target position and blend weight for one IK chain.
// Out-of-range chain indices are silently ignored.
void IK_Set_Target (IK_State *IK, int Chain_Index,
                    float Target_X, float Target_Y, float Target_Z, float Weight);

// Registers a new look-at IK chain (e.g. head tracking) and returns the chain
// index, or -1 if the chain table is full. The chain operates on a single end
// bone with no root or mid bone, constrained by the given angle limit in radians.
int IK_Add_Look_At (IK_State *IK, int Bone_End_Index, float Angle_Limit);

// Registers a new two-bone IK chain (e.g. arm or leg) and returns the chain
// index, or -1 if the chain table is full. The chain is enabled by default
// with full weight, a 180-degree joint angle limit, and a zero target position.
int IK_Add_Two_Bone (IK_State *IK, int Bone_Root_Index, int Bone_Mid_Index, int Bone_End_Index);

// Zeroes all fields in an IK_State, leaving it with no chains and IK disabled.
void IK_Initialize (IK_State *IK);

// Transitions the figure into ragdoll simulation. A snapshot of the current
// world-space bone pose is captured, all animation layers are faded out over
// Blend_Duration seconds, and the ragdoll blend timer is reset so the rendering
// layer can crossfade from the snapshot pose to the live physics pose.
void Animation_Blend_Begin_Ragdoll (Animation_Blend_State *Blend_State,
                                    const float World_Pose[][3][4],
                                    int Bone_Count, float Blend_Duration);

// Advances all active blend layers by Delta_Time seconds. For each layer:
// the playback cursor is advanced, looping or clamping at the sequence end;
// the fade-in weight ramp is updated if the layer is still blending in; and
// the fade-out weight ramp is updated if the layer is blending out, with the
// layer deactivated when the weight reaches zero. Also advances the ragdoll
// blend-out timer when a ragdoll is active. Returns 1 if any layer (or the
// ragdoll) is still active, 0 if all layers are idle.
int Animation_Blend_Tick (Animation_Blend_State *Blend_State,
                          const Articulated_Figure *Figure, float Delta_Time);

// Begins fading out the sequence on the given blend layer over Fade_Out_Duration
// seconds. A minimum fade duration of 0.001 s is enforced so weight never
// divides by zero. The layer is deactivated (Sequence_Index = -1) once the
// weight reaches zero during the next Tick call.
void Animation_Blend_Stop (Animation_Blend_State *Blend_State, int Layer_Index, float Fade_Out_Duration);

// Starts or restarts a sequence on the given blend layer. If Fade_In_Duration
// is greater than a small epsilon, the layer's weight begins at 0 and ramps
// to 1 over that duration; otherwise it snaps immediately to full weight.
void Animation_Blend_Play (Animation_Blend_State *Blend_State, int Layer_Index,
                           int Sequence_Index, float Fade_In_Duration, int Bone_Mask);

// Initialises an Animation_Blend_State to its default values. All layer
// sequence indices are set to -1 (inactive), and the ragdoll crossfade
// duration is seeded with the global default.
void Animation_Blend_Initialize (Animation_Blend_State *Blend_State);

// Movement_Style_Toggle declared after Player typedef (see below)

// Composes two tag transforms A and B into C, producing the world-space transform
// that results from placing B's local frame inside A's local frame. Both input
// transforms and the output are flat 12-float arrays laid out as:
//   [origin_xyz | col0_xyz | col1_xyz | col2_xyz]
// where col0/col1/col2 are the three columns of the 3×3 rotation matrix R.
//
// The composition is: C.origin = R_A * B.origin + A.origin
//                     C.axis_j = R_A * B.axis_j  (for each of the three column vectors)
void Tag_Compose (const float *Transform_A, const float *Transform_B, float *Transform_C);

// Searches the tag array for the named tag at the specified animation frame and
// copies its origin and 3×3 axis matrix into a flat 12-float array laid out as
// [origin_xyz | row0_xyz | row1_xyz | row2_xyz]. Returns 1 if the tag was found,
// or 0 if no tag with the given name exists in the frame's tag block.
int MD3_Find_Tag_At_Frame (const uint8_t *File_Data, int Tag_Count, int Tags_Offset,
                           int Frame_Index, const char *Tag_Name, float Out_Transform[12]);

// ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
//
// §9. Acceleration Structures
//
// ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

// Build the world geometry's bottom-level acceleration structure (BLAS). Uploads the scene vertex, index, and material buffers to the GPU,
// then constructs a single BLAS geometry entry covering all triangles. Uses PREFER_FAST_TRACE since the world is static.
Acceleration_Structure Build_World_Bottom_Level (const Scene *Scene_Data);

// Build a 3×4 TLAS transform from origin, yaw, and coordinate convention
void Figure_TLAS_Set (Figure_Instance *F, vec3 Origin, float Yaw_Deg, Convention_Kind Convention);

// Initialize a figure's BLAS: allocate vertex/index/texture-id GPU buffers, build initial BLAS with ALLOW_UPDATE for per-frame refit
void Figure_BLAS_Initialize (Figure_Instance *F);

// Rebuild a figure's BLAS after vertex data has changed (re-upload vertices, refit BLAS in-place)
void Figure_BLAS_Rebuild (Figure_Instance *F);

// Record a figure's BLAS rebuild into an existing command buffer (no submit - caller batches)
void Figure_Skeleton_Record (Figure_Instance *E, VkCommandBuffer Cmd, uint Frame_A, uint Frame_B, float Lerp_Factor);
void Figure_BLAS_Record (Figure_Instance *F, VkCommandBuffer Cmd);

// Pre-allocate the top-level acceleration structure (TLAS) for up to Maximum_Instances instance entries
void Top_Level_Initialize (uint Maximum_Instances);

// Rebuild the TLAS each frame from the world BLAS plus all active figures in the pool
void Top_Level_Rebuild (Acceleration_Structure *World, Figure_Pool *Pool);

// Record a TLAS rebuild into an existing command buffer (no submit - caller batches)
void Top_Level_Record (Acceleration_Structure *World, Figure_Pool *Pool, VkCommandBuffer Cmd);

// Batch all BLAS rebuilds + TLAS rebuild into a single command buffer submission (eliminates per-figure vkQueueWaitIdle)
void Acceleration_Rebuild_All (Acceleration_Structure *World, Figure_Pool *Pool);

// ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
//
// §10. Physics
//
//   GPU-only physics via ray tracing against the TLAS. The compute shader traces rays from the player's expanded shape against world
//   geometry, resolves contacts via a slide-move algorithm, and writes back the updated GPU_Player state.
//
//   Convex hull support uses hill-climbing with adjacency for O(√n) amortized queries on hulls with ≥64 vertices, falling back to O(n)
//   brute-force for smaller hulls.
//
// ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

// Convex Hull Limits
#define HULL_MAX_VERTS    256 // Per-hull vertex cap (matches GPU array size in GPU_Hull)
#define HULL_MAX_ADJ      16  // Maximum adjacency entries per vertex (for hill-climb support)
#define HULL_MAX_FACES    512 // Quickhull internal face cap during construction
#define HULL_MAX_ENTITIES 32  // Maximum simultaneous hull collider instances

// Per-frame hull recomputation: when enabled, the convex hull is rebuilt on the GPU every frame
// after the skinning pass completes. This keeps the collision hull accurate for animated/deformable
// meshes at the cost of one extra compute dispatch per skinned entity per frame.
#define HULL_RECOMPUTE_PER_FRAME 0

// Collider Shape Enumeration
//
// Six collider shapes, each defining a support function s(d̂) : S^2 > ℝ³ from unit directions to surface offsets. The GPU physics compute
// shader switches on this enum to select the appropriate Minkowski support mapping.
//
enum Collider_Shape {SHAPE_SPHERE,    // Projectiles:       s(d̂) = d̂ · r
                     SHAPE_CAPSULE,   // Player, NPCs:      s(d̂) = d̂ · r + (0, sign(d̂.y) · spine, 0)
                     SHAPE_AABB,      // Crates, elevators: s(d̂) = sign(d̂) ⊙ extents
                     SHAPE_CYLINDER,  // Barrels, columns:  s(d̂) = (d̂.xz/‖d̂.xz‖ · r, sign(d̂.y) · h, 0)
                     SHAPE_ELLIPSOID, // Vehicles:          s(d̂) = normalize(d̂ ⊘ axes) ⊙ axes · ‖...‖
                     SHAPE_HULL,      // Arbitrary models   s(d̂) = argmax(v · d̂) over vertex set
                     SHAPE_CONE};     // Traffic cones:     apex at +spine, base disc at -spine, radius r

// GPU-resident player state uploaded to the physics compute shader
typedef struct {
  vec3  Position;      float Step_Offset;
  vec3  Velocity;      float Pad_B;
  float Yaw, Pitch;
  int   On_Ground;
  int   Jump_Held;
  vec3  Ground_Normal; float Pad_C;
  int   Ground_Plane;
  int   Ducked;
  float View_Height;   
  float Stuck_Time;
  float Speed_Last;   
  int   Shape;         float Pad_Align[2]; // Previous frame speed; active collider shape (enum Collider_Shape)
  vec3  Extents;       float Pad_D;        // Half-extents / radii / semi-axes (shape-dependent)
  float Spine;
  int Ground_Flags;    float Pad_E[2];     // Capsule spine half-length; ground surface material flags
  // Physics constants (set per-world at init, read by shader every frame)
  float Walk_Normal;   // Min surface normal.y for walkable floor
  float Ground_Dist;   // Ground trace probe window
  float Snap_Down;     // Max ground snap-down distance
  float Push_Up;       // Max ground push-up distance
  float Vel_Clamp;     // Max velocity magnitude
  float Step_Decay;    // Stair step camera smoothing rate
  float View_Lerp;     // View height interpolation speed
  float Pitch_Limit;   // Max look pitch (radians)
  float Recover_Max;   // Max unstuck push per direction per frame
  float Recover_Min;   // Min penetration depth to trigger recovery
  float Tick_Rate;     // Physics sub-step rate (Hz) — higher = more sub-steps per frame
  float Pad_F;
  // Diagnostic toggles (written by CPU from CVars, read by shader)
  int   Diag_No_Recover;   // Disable recover()
  int   Diag_No_Snap;      // Disable ground_trace snap
  int   Diag_No_Step;      // Use slide_move instead of step_move
  int   Diag_Pad_A;
  // Diagnostic outputs (written by shader, read back by CPU)
  float Diag_Ground_Correction;  // ground_trace Y correction this frame
  float Diag_Recover_Push;       // length of recover push vector
  int   Diag_Slide_Bumps;        // collision bumps in slide_move
  int   Diag_Sim_Steps;          // sub-steps computed this frame
} GPU_Player;

// Per-frame input delivered to the physics compute shader via push constants for both input state and CVar-driven constants
typedef struct {

  // Input
  int Forward, Back, Left, Right;                                           
  int Jump, Fire, Crouch, Pad_I;                                            
  float Delta_X, Delta_Y, Dt;         

  // Physics                                       
  float Gravity;                                                             
  float Friction, Stop_Speed, Ground_Accel, Air_Accel;                         
  float Max_Speed, Jump_Vel, Overbounce, Step_Size;                    

  // View        
  float Mouse_Sensitivity, View_Height, Crouch_Height, Spine;                 

  // weapon
  float Rocket_Speed, Rocket_Lifetime, Fire_Cooldown_Val, Splash_Radius;

  // Physics collision tuning
  float Probe_Count, Cone_Rays, Skin_Width, Cone_Angle;
} GPU_Input;

// Projectile
typedef struct {
  vec3  Position; float Pad_A;   // World position
  vec3  Velocity;                // Units per second
  float Lifetime;                // Seconds remaining before expiry
  int   Active;                  // Boolean: 1 = live, 0 = dead
  int   Material_Hit;            // Surface material on impact (for sound selection)
  float Radius;                  // Collision radius
  float Damage;                  // Base damage on impact (before body-part multiplier)
  float Hit_U, Hit_V;            // UV coordinates at impact point (for damage map sampling)
  int   Instance_Hit; int Pad_B; // Packed TLAS instanceCustomIndex of hit object (-1 = none, low 8 bits = figure slot)
} Projectile;

typedef struct {
  Projectile Slots[MAX_PROJECTILES]; // Fixed-size projectile array
  int        Count;                  // Active projectile count
  float      Fire_Cooldown;          // Time until next shot allowed
  float      Pad[2];
} Projectile_Pool;
Projectile_Pool Projectiles;

// GPU-side mirror of Projectile_Pool (std430, uploaded to physics compute)
typedef struct {
  vec3  Position;    float Pad_A;
  vec3  Velocity;    float Lifetime;
  int   Active;      int   Material_Hit;
  float Radius;      float Damage;
  float Hit_U, Hit_V; // UV at impact point (written by GPU on hit)
  int   Instance_Hit; // TLAS instance that was hit (-1 = none)
  int   Pad_B;
} GPU_Projectile;

typedef struct {
  GPU_Projectile Slots[MAX_PROJECTILES];
  int   Count;
  float Fire_Cooldown;
  float Pad[2];
} GPU_Projectile_Pool;

// Ragdoll system 
//
// Skeleton stabilization (split impulse, bias) via rayQueryEXT collision against TLAS
//
#define JOINT_DISTANCE 0 // Maintains bone-to-bone distance (ball-and-socket)
#define JOINT_ANGULAR  1 // Cone-twist angular limit between bones

// GPU-side ragdoll body (point mass with Verlet state)
typedef struct {
  float Position  [3]; float Inv_Mass;  // xyz + inverse mass (0 = kinematic/fixed)
  float Prev_Pos  [3]; float Radius;    // Previous position for Verlet + collision radius
  float Velocity  [3]; float Damping;   // Explicit velocity for PhysX-style split impulse + per-body damping
  int   Bone_Index;    int   Colliding; // Maps back to skeleton bone, collision flag
  float Pad_R     [2];
} GPU_Ragdoll_Body;                    

// GPU-side ragdoll constraint
typedef struct {
  int   Body_A, Body_B;       // Indices into the body array
  int   Type;                 // JOINT_DISTANCE or JOINT_ANGULAR
  float Rest_Length;          // Rest distance (distance constraint) or rest angle (angular)
  float Min_Angle, Max_Angle; // Angular limits (cone half-angle, twist limit) - radians
  float Compliance;           // XPBD compliance (α = 1/stiffness, 0 = infinitely stiff)
  float Lambda;               // Accumulated Lagrange multiplier (warm-start, PhysX-style temporal coherence)
} GPU_Ragdoll_Joint;  

// Complete GPU ragdoll state
typedef struct {
  GPU_Ragdoll_Body  Bodies [RAGDOLL_MAX_BODIES];
  GPU_Ragdoll_Joint Joints [RAGDOLL_MAX_JOINTS];
  int   Body_Count, Joint_Count;
  int   Active;         // Where 0 = dormant, 1 = simulating
  int   Substeps;       // Substeps per frame (CVar-driven)
  float Gravity;        // Ragdoll gravity (may differ from player gravity)
  float Global_Damping; // Velocity damping factor per substep
  float Floor_Y;        // Simple floor plane for fallback collision
  float Pad_RG;
} GPU_Ragdoll;

typedef struct {
  GPU_Ragdoll Ragdolls [RAGDOLL_MAX_ACTIVE];
  int         Count; 
  int         Pad_RP [3];
} GPU_Ragdoll_Pool;

// GPU-side rigid body for XPBD physics
#define ENTITY_MAX_ACTIVE  256
#define CONTACT_MAX        1024

typedef struct {
  vec3  Position;    float Inv_Mass;        // 0 = infinite mass (static)
  vec4  Orientation;                        // quaternion (x,y,z,w)
  vec3  Velocity;    float Restitution;
  vec3  Angular_Vel; float Friction;
  vec3  Inv_Inertia; float Pad_RB;
  vec3  Extents;     float Radius;
  int   Shape;       int   On_Ground;
  int   Active;      int   Sleep_Counter;
  vec3  Force_Accum; float Pad_RB2;
  vec3  Torque_Accum;float Pad_RB3;
} GPU_Rigid_Body;                           // 144B

typedef struct {
  int   Body_A;      int   Body_B;
  float Penetration; float Pad_C;
  vec3  Normal;      float Pad_C2;
  vec3  Point;       float Lambda;
} GPU_Contact;

typedef struct {
  GPU_Rigid_Body Bodies   [ENTITY_MAX_ACTIVE];
  GPU_Contact    Contacts [CONTACT_MAX];
  int            Count;
  int            Contact_Count;
  int            Pad_EP [2];
} GPU_Entity_Pool;

#define GPU_Entity GPU_Rigid_Body

// Spatial hash for broad-phase collision
#define SPATIAL_HASH_SIZE  4096
#define SPATIAL_HASH_DEPTH 8

typedef struct {
  int Entries [SPATIAL_HASH_SIZE][SPATIAL_HASH_DEPTH];
  int Counts  [SPATIAL_HASH_SIZE];
} GPU_Spatial_Hash;

// Island detection via parallel union-find
typedef struct {
  int Parent     [ENTITY_MAX_ACTIVE];
  int Sleep_Flag [ENTITY_MAX_ACTIVE];
} GPU_Island_Data;

// Push constants for the post-processing compute shader
typedef struct {
  float    Time;            // Full-precision seconds since start
  uint32_t Dt_Frame;        // Bits [15:0] = half(Delta_Time),     [31:16] = Frame_Count
  uint32_t Velocity;        // Bits [15:0] = half(Velocity_X),     [31:16] = Half (Velocity_Z)
  uint32_t Speed_Exposure;  // Bits [15:0] = half(Speed),          [31:16] = Half (Exposure)
  uint32_t Bloom_Vignette;  // Bits [15:0] = half(Bloom_Strength), [31:16] = Half (Vignette_Strength)
  uint32_t Reproject[8];    // Packed via packHalf2x16 - compressed 4 by 4 reprojection matrix (Proj * Prev_View * Inv_View)
  uint32_t Inv_Proj_Diag;   // Bits [15:0] = half(InvProj[0][0]),     [31:16] = Half (InvProj[1][1])
  uint32_t Sun_Screen_Pos;  // Bits [15:0] = half(Sun_Screen_U),      [31:16] = Half (Sun_Screen_V) - for god rays
  uint32_t Sun_Params;      // Bits [15:0] = half(God_Ray_Intensity), [31:16] = Half (Sun_On_Screen) (0 or 1)

  // Post-process tuning knobs (half2x16 packed from CVars)
  uint32_t PP_Firefly; // Half (Headroom),     Half (Bias)
  uint32_t PP_CAS;     // Half (Amount),       Half (Mix)
  uint32_t PP_TAA_A;   // Half (Static_Floor), Half (Sigma)
  uint32_t PP_TAA_B;   // Half (Move_Lo),      Half (Move_Hi)
  uint32_t PP_Shadow;  // Half (Shadow_Floor), Half (LM_Shadow_Floor)
} GPU_Postprocess_Push;  

// Menu Overlay GPU Types
#define MENU_MAX_LINES       64  // Maximum console lines visible at once
#define MENU_MAX_CHARS       128 // Maximum characters per line
#define MENU_MAX_COMPLETIONS 9   // Max autocomplete suggestions shown
#define MENU_MAX_SLIDERS     64  // Max slider entries in SSBO

// Push constants for the menu overlay compute shader
typedef struct {
  uint32_t Resolution[2];          // Viewport width, height
  uint32_t Line_Count;             // Number of output lines in the SSBO
  uint32_t Cursor_Pos;             // Input cursor position (character index)
  float    Opacity;                // Console background opacity (0 = hidden, 1 = full)
  float    Drop_T;                 // Drop animation factor (0 = closed, 1 = fully open)
  uint32_t Has_Input;              // Its 1 if input line is present (last line in SSBO is the input prompt)
  uint32_t Completion_Count;       // Number of autocomplete suggestions (lines after input in SSBO)
  uint32_t Completion_Sel;         // Currently highlighted completion (-1 = none)
  uint32_t Slider_Mode;            // 1 = show sliders (menu mode, not console)
  uint32_t Mouse_X, Mouse_Y;      // Mouse position in render coords
  uint32_t Slider_Count;           // Number of sliders in SSBO
  uint32_t Slider_Hover;           // Index of hovered slider (-1 = none)
  uint32_t Slider_Scroll;         // Scroll offset for slider list
  uint32_t Pad;
} GPU_Menu_Push;

// Per-line entry in the console text SSBO - each line is an array of Unicode codepoints + style
typedef struct {
  uint32_t Codepoints [MENU_MAX_CHARS]; // Unicode values (0-terminated)
  uint32_t Length;                      // Number of valid characters
  uint32_t Style;                       // Console_Style enum value
  uint32_t Pad[2];
} GPU_Console_Line;

// GUI Element System
//
// Each GUI_Element maps to one "windowDef":
//   windowDef Name { rect x,y,w,h; forecolor r,g,b,a; backcolor r,g,b,a; text "..."; ... }
//
// The system supports nested elements (parent-child), text selection, cursor/focus tracking,
// and flexbox-style auto-layout within containers.
//
#define GUI_MAX_ELEMENTS 128 // Max elements in the GUI tree
#define GUI_MAX_TEXT     256 // Max text length per element
#define GUI_MAX_CHILDREN 16  // Max direct children per element

typedef enum {
  GUI_WINDOW, // Standard rectangular window (Doom3: windowDef)
  GUI_EDIT,   // Text input field (Doom3: editDef)
  GUI_LIST,   // Scrollable list (Doom3: listDef)
  GUI_CHOICE, // Toggle/dropdown (Doom3: choiceDef)
  GUI_SLIDER, // Slider bar (Doom3: sliderDef)
  GUI_RENDER, // 3D model viewport (Doom3: renderDef)
  GUI_LABEL   // Static text label (no interaction)
} GUI_Element_Kind;

typedef enum {GUI_ALIGN_LEFT, GUI_ALIGN_CENTER, GUI_ALIGN_RIGHT} Text_Align;

typedef enum {
  GUI_FLEX_NONE,
  GUI_FLEX_ROW,
  GUI_FLEX_COLUMN
} Flex_Direction;
typedef struct {
  GUI_Element_Kind Kind;
  int         Parent; // Index into GUI_State.Elements (-1 = root)
  int         Children[GUI_MAX_CHILDREN];
  int         Child_Count;

  // Layout
  vec4           Rect;    // x, y, width, height relative to parent
  Flex_Direction Flex;    // Flexbox layout mode for children
  float          Gap;     // Spacing between flex children
  vec4           Padding; // Spacing around top, right, bottom, left

  // Visual
  vec4       Forecolor;   // Text RGBA
  vec4       Backcolor;   // Background RGBA
  vec4       Hovercolor;  // Text color on hover
  vec4       Bordercolor; // Border RGBA
  float      Bordersize;  // Border thickness in pixels
  float      Textscale;   // Font scale 
  Text_Align Textalign;   // Text alignment

  // Content
  char Text[GUI_MAX_TEXT]; // Display text 
  char Name[64];           // Element name for scripting 
  int  Text_Length;

  // State
  int Visible;   // When 1 = shown, 0 = hidden 
  int No_Events; // When 1 = ignore mouse 
  int Focused;   // When 1 = has keyboard focus
  int Hovered;   // When 1 = mouse is over this element
  int Pressed;   // When 1 = mouse button held

  // Text selection
  int Sel_Start; // Selection start character index (-1 = no selection)
  int Sel_End;   // Selection end character index
  int Cursor;    // Text cursor position (caret)

  // CVar binding 
  int CVar_Index; // Bound CVar index (-1 = none)
} GUI_Element;

typedef struct {
  GUI_Element Elements[GUI_MAX_ELEMENTS];
  int         Element_Count;

  // Cursor state (virtual 640x480 coordinates)
  float Cursor_X, Cursor_Y;
  int   Focus_Element;  // Index of element with keyboard focus (-1 = none)
  int   Hot_Element;    // Index of element under cursor (-1 = none)
  int   Active_Element; // Index of element being pressed (-1 = none)

  // Text selection drag state
  int Selecting;   // When 1 = mouse drag selecting text
  int Sel_Element; // Which element has active text selection
  int Sel_Anchor;  // Character index where selection started

  // Transition animation targets
  float Transition_T;// Current transition time
} GUI_State;

// Global GUI state
GUI_State GUI;

