  CVar_Set_Float (e_sky_zenith_r,    E->Sky_Zenith.x);
  CVar_Set_Float (e_sky_zenith_g,    E->Sky_Zenith.y);
  CVar_Set_Float (e_sky_zenith_b,    E->Sky_Zenith.z);
  CVar_Set_Float (e_sky_horizon_r,   E->Sky_Horizon.x);
  CVar_Set_Float (e_sky_horizon_g,   E->Sky_Horizon.y);
  CVar_Set_Float (e_sky_horizon_b,   E->Sky_Horizon.z);
  CVar_Set_Float (e_sky_intensity,   E->Sky_Intensity);
  CVar_Set_Float (e_ambient_up_r,    E->Ambient_Up.x);
  CVar_Set_Float (e_ambient_up_g,    E->Ambient_Up.y);
  CVar_Set_Float (e_ambient_up_b,    E->Ambient_Up.z);
  CVar_Set_Float (e_ambient_dn_r,    E->Ambient_Down.x);
  CVar_Set_Float (e_ambient_dn_g,    E->Ambient_Down.y);
